        self._training_custom_frame.grid(row=12, column=0, columnspan=2, sticky=tk.W, padx=15, pady=(4, 4))
        self.training_block_vars = {}  # block_name -> BooleanVar

        tc_header = ttk.Frame(self._training_custom_frame)
